void ui_event_gcashbackbtn(lv_event_t * e)
{
    if(e == NULL)
        return;

    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_CLICKED)
    {
        gcashSelectedAmount = 0;

        if(ui_amount10cb)
            lv_obj_clear_state(
                ui_amount10cb,
                LV_STATE_CHECKED
            );

        if(ui_amount20cb)
            lv_obj_clear_state(
                ui_amount20cb,
                LV_STATE_CHECKED
            );

        if(ui_amount30cb)
            lv_obj_clear_state(
                ui_amount30cb,
                LV_STATE_CHECKED
            );

        if(ui_AmountoPaylbl)
            lv_label_set_text(
                ui_AmountoPaylbl,
                "PHP 0.00"
            );

        // CORRECT BACK FUNCTION
        coin_back_clicked(e);
    }
}


