// ============================================================
// PAY BUTTON
// ============================================================

void ui_event_GcashPaybtn(lv_event_t * e)
{
    if(e == NULL)
        return;

    lv_event_code_t event_code = lv_event_get_code(e);

    if(event_code == LV_EVENT_CLICKED)
    {
        // Pay button -> proceed to the GCash QR screen.
        // Do not call gcash_clicked() here; that function returns
        // to/reloads the amount-selection screen.
        if(gcashSelectedAmount == 0)
        {
            // No amount selected yet. Stay on this screen.
            return;
        }

        // Show the selected amount on the QR screen.
        if(ui_GcashAmountlbl)
        {
            char amountText[16];
            snprintf(amountText, sizeof(amountText), "%u.00", gcashSelectedAmount);
            lv_label_set_text(ui_GcashAmountlbl, amountText);
        }

        _ui_screen_change(
            &ui_GcashQRsc,
            LV_SCR_LOAD_ANIM_NONE,
            0,
            0,
            &ui_GcashQRsc_screen_init
        );
    }
}


